// Serial — a pushbutton on pin 2, reporting every change to the serial monitor.
//
// The delay is a debounce. A real switch does not change level cleanly: it
// chatters for about a millisecond, and without this the same press would report
// several times. Turn on "Switch bounce" in the Run menu, then delete the
// millis() condition below and Run again to see exactly what that means.

const int BUTTON = 2;

int last = HIGH;
unsigned long lastChange = 0;

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  Serial.begin(9600);
  Serial.println("ready");
}

void loop() {
  int now = digitalRead(BUTTON);
  if (now != last && millis() - lastChange >= 5) {
    last = now;
    lastChange = millis();
    Serial.println(now == LOW ? "pressed" : "released");
  }
}
